      "3. Cooking & Simmering: Introduce the prepared Oats Vegetable Khichdi ingredients and diced vegetables. Gently stir-fry, add required warm water or broth, cover and simmer on low heat until tender and thoroughly infused.",
      "4. Rest & Garnish: Remove from flame, allow to rest covered for 2 minutes to lock in aromas. Drizzle fresh lemon juice and chopped fresh herbs before serving warm."
